#!/usr/bin/env bash
# Regenerates SUPPORTED.md from manifests/*.env and the machine-readable status
# table in manifests/SECURITY-REVIEW.md. It reads no registry and needs no
# network: this page is the project's support policy (what each series is built
# from, what the review record says, what the two published names mean), and
# which tags exist or what a digest resolves to is a registry fact that the
# registry answers. Supported is not published, and copying the registry's answer
# in here would make every release a documentation edit.
# SUPPORTED.md is generated — do not edit it by hand. CI regenerates the file and
# compares it against the committed one, and because the output depends only on
# the tree, that comparison is byte-exact and reproducible offline.
set -Eeuo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
OUT="${ROOT}/SUPPORTED.md"
# version-branch: series-allowlist
SUPPORTED_VERSIONS="5.6 7.0 7.1 7.2 7.3 7.4 8.0 8.1"

status_for() {
  # Parse rows of the form: | <version> | <status> |  from SECURITY-REVIEW.md.
  # A version may appear in other tables in that file (the pin table does), so
  # only a row whose second column is one of the known status words counts --
  # otherwise the first matching version line wins and reports a tag name as a
  # review status.
  local ver="$1" st
  st="$(awk -F'|' -v ver="$ver" '
    BEGIN {
      split("unreviewed patch-present-not-tested tested-in-CI approved-for-staging approved-for-production", ok, " ")
      for (i in ok) valid[ok[i]] = 1
    }
    { gsub(/^[ \t]+|[ \t]+$/, "", $2); gsub(/^[ \t]+|[ \t]+$/, "", $3) }
    $2 == ver && ($3 in valid) { print $3; exit }
  ' "${ROOT}/manifests/SECURITY-REVIEW.md" 2>/dev/null || true)"
  case "$st" in
    unreviewed|patch-present-not-tested|tested-in-CI|approved-for-staging|approved-for-production)
      printf '%s' "$st"; return ;;
  esac
  printf 'unreviewed'
}

pinned_php() {
  # $1 = series. What this repository's manifest pins as the PHP version --
  # SOURCE_REF, the release tag the manifest also records the peeled commit of.
  # Plain sed, because sourcing the whole manifest to obtain one field would run
  # project configuration for a string.
  sed -n 's/^SOURCE_REF=//p' "${ROOT}/manifests/${1}.env" 2>/dev/null | head -1 | tr -d '"'
}

upstream_last() {
  # $1 = series -> "<last official release> <released> <announced end of life>".
  # php.net's own record, read from its unsupported-versions table and each
  # series' changelog and news archive on 2026-11-05. These are closed facts --
  # a branch php.net has stopped cannot gain another release -- so they are
  # carried as data rather than scraped on every run, and a status page that
  # could rewrite its own history is not a status page. The columns are
  # deliberately not assumed to be in order: php.net announced 5.6's end of life
  # on 2018-12-31 and shipped 5.6.40 on 2019-01-10, and shipped 7.0.33 on
  # 2018-12-06 before announcing 7.0's end of life on 2019-01-10.
  case "$1" in
    5.6) printf '5.6.40 2019-01-10 2018-12-31' ;;
    7.0) printf '7.0.33 2018-12-06 2019-01-10' ;;
    7.1) printf '7.1.33 2019-10-24 2019-12-01' ;;
    7.2) printf '7.2.34 2020-10-01 2020-11-30' ;;
    7.3) printf '7.3.33 2021-11-18 2021-12-06' ;;
    7.4) printf '7.4.33 2022-11-03 2022-11-28' ;;
    8.0) printf '8.0.30 2023-08-03 2023-11-26' ;;
    8.1) printf '8.1.34 2025-12-18 2025-12-31' ;;
    *)   printf '? - -' ;;
  esac
}

{
  echo "# Supported versions"
  echo
  echo "<!-- GENERATED by tools/gen-supported.sh — do not edit by hand. -->"
  echo "<!-- Source of truth: manifests/*.env + manifests/SECURITY-REVIEW.md status table. Registry state is not recorded here; see \"Checking what the registry serves\" below for how to read it. -->"
  echo
  echo "Read [SECURITY.md](SECURITY.md#responsibility-boundary) before using any image"
  echo "from this project. This page is the support policy: which base and OpenSSL route"
  echo "each series is built on, what it is pinned to, what the review record says about"
  echo "it, and what the published names mean. A row being filled in does **not** mean"
  echo "the version is secure, and it does not mean an image exists to pull. Why a pin"
  echo "or a base was chosen is in \`manifests/SECURITY-REVIEW.md\` and"
  echo "[manifests/OS-CVE-STATUS.md](manifests/OS-CVE-STATUS.md), and how a build or a"
  echo "release run works is in [MAINTAINING.md](MAINTAINING.md)."
  echo
  echo "| Version | OpenSSL route | Debian base | Base pin | Source repo | Variants | Composer | Patches | Security review | Extensions |"
  echo "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |"
  for v in $SUPPORTED_VERSIONS; do
    f="${ROOT}/manifests/${v}.env"
    if [ ! -f "$f" ]; then
      # Ten columns, same order as the header: a series with no manifest is a
      # row that says so rather than a row that is short.
      echo "| ${v} | — | — | — | manifest missing | — | — | — | unreviewed | — |"
      continue
    fi
    # Trusted project configuration, not untrusted input.
    # shellcheck source=/dev/null
    ( . "$f"
      route="${OPENSSL_ROUTE:-?}"
      case "${PHP_SRC_REPO:-}" in
        # The backports fork is the source of record for every series; the
        # official tree is a policy violation (build.sh and the Dockerfile both
        # refuse it), so label it as such rather than presenting it as a choice.
        # Match the allowed fork first so a repo string that happens to contain
        # both patterns can never be mislabelled as a violation.
        *php-src-backports*) repo="shivammathur/php-src-backports" ;;
        *php/php-src*) repo="official php/php-src — policy violation" ;;
        "") repo="unset" ;;
        *) repo="custom (see manifest)" ;;
      esac
      variants="${BUILD_VARIANTS:-none}"
      # Composer policy default; the Dockerfile is the authoritative source for
      # these pins (keep in sync with its Composer step). version-branch:
      # composer-policy
      case "$v" in
        5.6|7.0|7.1) policy_composer="1.10.28" ;;
        *)           policy_composer="2.11.0" ;;
      esac
      composer="${COMPOSER_VERSION:-$policy_composer}"
      if [ -n "${COMPOSER_VERSION:-}" ] && [ "${COMPOSER_VERSION}" != "$policy_composer" ] \
         && [ -z "${COMPOSER_SHA256:-}" ]; then
        composer="${composer} (override, digest unverified)"
      fi
      # "@sha256:" alone is not a pin — an unfilled manifest ships
      # "@sha256:REPLACE_WITH_DIGEST", and calling that "pinned by digest" in a
      # status table would be exactly the false claim this file exists to avoid.
      case "${BASE_IMAGE:-}" in
        REPLACE_WITH*|"") base="template (unpinned)" ;;
        *@sha256:*)
          if printf '%s' "${BASE_IMAGE##*@sha256:}" | grep -Eq '^[0-9a-f]{64}$'; then
            base="pinned by digest"
          else
            base="digest placeholder — not buildable"
          fi
          ;;
        *) base="UNPINNED — invalid" ;;
      esac
      # Which Debian a series is built on is a separate fact from whether that
      # choice is pinned, and a status table that printed only the second left
      # the reader to compare base images in another document. The ref is
      # printed without its digest: the digest is in the manifest and in the
      # image, and a 64-hex column here would make every row unreadable.
      base_ref="${BASE_IMAGE:-}"
      base_ref="${base_ref%%@sha256:*}"
      [ -n "$base_ref" ] || base_ref="—"
      if [ "${PATCHSET_APPROVED:-0}" = "1" ]; then
        patches="approved"
      else
        patches="pending review"
      fi
      # Extension set = the kit baseline plus whatever this manifest adds. The
      # baseline is restated here because SUPPORTED.md is what a reader compares
      # versions with; the authoritative copy lives in the Dockerfile's guard
      # step (ext_baseline_core / ext_baseline_pecl), and the validate gate runs
      # tools/check-ext-baseline.sh to fail CI if the two disagree. The cell
      # shows the baseline, then this series' additions in parentheses, so
      # "ships more" is distinguishable from "ships the same thing".
      ext_core="openssl curl mysqli pdo_mysql mbstring zip gd zlib"
      ext_pecl="apcu redis memcached"
      # mcrypt is baseline core on exactly the series that can build it (in core
      # through 7.1; the PECL replacement floors at PHP 7.2.0), mirroring the
      # Dockerfile guard step's version-conditional append.
      case "$v" in
        5.6|7.0|7.1) ext_core="${ext_core} mcrypt" ;;
      esac
      # set -f around the unquoted expansions: a list that is empty or padded
      # with spaces must split into words without the names being globbed
      # against the filesystem.
      set -f
      # shellcheck disable=SC2086
      set -- ${PHP_EXTENSIONS:-} ${PECL_EXTENSIONS:-}
      ext_added="$*"
      set +f
      ext_cell="${ext_core} ${ext_pecl}"
      if [ -n "$ext_added" ]; then
        ext_cell="${ext_cell} (+${ext_added})"
      fi
      echo "| ${v} | ${route} | ${base_ref} | ${base} | ${repo} | ${variants} | ${composer} | ${patches} | $(status_for "$v") | ${ext_cell} |"
    )
  done
  echo
  echo "How to read a row. \`Debian base\` is the OS the image is built on and \`Base pin\`"
  echo "says whether that ref is pinned by digest -- a placeholder or an unpinned ref is"
  echo "stated as it is, never rounded up to \"pinned\". \`Source repo\` is the source of"
  echo "record the manifest points at, \`Variants\` what a release publishes for the"
  echo "series, and \`Composer\` the release the image installs. \`Patches\` is the human"
  echo "patchset decision (\`PATCHSET_APPROVED=1\` reads \`approved\`); a row reading"
  echo "\`pending review\` is never built or published. \`Security review\` is the status"
  echo "recorded in \`manifests/SECURITY-REVIEW.md\`: \`tested-in-CI\` means the image"
  echo "passes the project's CI build and runtime checks, which is not an approval and"
  echo "not a claim that a tag exists. Whether a tag exists is a registry fact, and"
  echo "\"Checking what the registry serves\" below is how to read it."
  echo
  echo "## Upstream end of life"
  echo
  echo "Every series above is end-of-life upstream: \`php/php-src\` stopped releasing for"
  echo "these lines, which is why the source of record is a backports fork and not PHP"
  echo "itself. The dates are php.net's own record (its unsupported-versions table plus"
  echo "each series' changelog and news archive, read 2026-11-05) and they are closed"
  echo "facts, so they are stored here rather than fetched at generation time."
  echo
  echo "| Series | Last official release | Released | Announced end of life | Pinned here |"
  echo "| --- | --- | --- | --- | --- |"
  for v in $SUPPORTED_VERSIONS; do
    read -r u_last u_rel u_eol <<<"$(upstream_last "$v")"
    u_pin="$(pinned_php "$v")"
    if [ -z "$u_pin" ]; then
      u_cell="no manifest"
    elif [ "$u_pin" = "$u_last" ]; then
      u_cell="\`${u_pin}\`"
    else
      # Saying so is the point: a series pinned below php.net's final release is
      # one more version behind than the row above implies.
      u_cell="\`${u_pin}\` -- below the last official release"
    fi
    echo "| ${v} | \`${u_last}\` | ${u_rel} | ${u_eol} | ${u_cell} |"
  done
  echo
  echo "The release and EOL columns are not in order on every row, and that is what"
  echo "php.net published: 5.6's end of life was announced on 2018-12-31 and \`5.6.40\`"
  echo "arrived on 2019-01-10, while \`7.0.33\` came on 2018-12-06, before 7.0's announced"
  echo "end of life on 2019-01-10, with nothing after it. \"Pinned here\" is this"
  echo "repository's own \`PHP_VERSION\`, read from the manifest at generation time --"
  echo "every series sits on php.net's final release today, and a row that stops saying"
  echo "so means the pin is behind it."
  echo
  echo "## Composer"
  echo
  echo "The Composer column is the release each image installs. Composer 2.x requires"
  echo "PHP >= 7.2.5, so PHP 5.6/7.0/7.1 stay on the final 1.x release (1.10.28) and"
  echo "7.2–8.1 ship 2.11.0. A manifest that overrides the policy pin without also"
  echo "pinning a digest is labelled as unverified in its row. Where those two numbers"
  echo "come from and how the built image verifies them is"
  echo "[MAINTAINING.md](MAINTAINING.md#composer-trust-model); the digests themselves"
  echo "are recorded in \`/opt/php/BUILD-PROVENANCE\` inside the image."
  echo
  echo "## Release tags"
  echo
  echo "Published images are \`ghcr.io/muffetlab/php\`, and a release writes two names per"
  echo "series and variant -- no third name, and no other registry:"
  echo
  echo "- \`ghcr.io/muffetlab/php:<minor>-<variant>\` — the recommended deploy tag; it floats, and only within its own series"
  echo "- \`ghcr.io/muffetlab/php:<full-php-version>-r<revision>-<variant>\` — the exact tag; \`8.1.34-r1-fpm\` is the first image built from PHP 8.1.34, \`8.1.34-r2-fpm\` the next build of it"
  echo
  echo "There is no \`latest\` tag published for any variant: neither name above is one,"
  echo "and \`<minor>-<variant>\` is the only name that moves -- it cannot change major"
  echo "version. Choose the series from the table above."
  echo "[MAINTAINING.md](MAINTAINING.md#publishing-images) holds the rest of the model:"
  echo "why no \`latest\` is published, what each of the four release inputs carries, and"
  echo "how a run decides which series to build."
  echo
  echo "The release pipeline treats exact tags as immutable, so the highest revision the"
  echo "registry serves for a PHP version is its newest image: a deployment that pinned"
  echo "an exact name has to move to a newer revision -- or to \`<minor>-<variant>\` -- to"
  echo "receive a fix."
  echo
  echo "## Checking what the registry serves"
  echo
  echo "Which tags exist, and what each one resolves to, is the registry's answer, not"
  echo "this page's. A release moves names and digests, so a table of them here would be"
  echo "out of date the moment it earned its place, and a reader who needed the current"
  echo "answer would be steered at a stale one. Read it where it lives:"
  echo
  echo "- one name: \`docker buildx imagetools inspect ghcr.io/muffetlab/php:8.1-fpm\` prints the manifest list the tag resolves to, with each platform's digest"
  echo "- the whole namespace: the package list for \`ghcr.io/muffetlab/php\` shows the tags the registry serves today"
  echo
  echo "A name the registry does not serve answers \"manifest unknown\". A complete,"
  echo "approved and reviewed manifest is a precondition for a release, not a claim that"
  echo "one happened: a series is published by the release run that selects it. The two"
  echo "names a release writes are the ones in \"Release tags\" above; anything else in"
  echo "the namespace came from outside the pipeline, and"
  echo "[MAINTAINING.md](MAINTAINING.md#publishing-images) says what a run is allowed to"
  echo "write."
  echo
  echo "Each tag is a multi-arch manifest list covering \`linux/amd64\` and \`linux/arm64\`;"
  echo "\`docker pull\` selects the matching platform automatically. There are no"
  echo "architecture-suffixed tags."
  echo
  echo "The OpenSSL route is not part of a tag name either: one route is fixed per"
  echo "series, so a suffix could express no choice a deployment makes. The"
  echo "\`OpenSSL route\` column above is the answer, and the image carries it in"
  echo "\`/opt/php/BUILD-PROVENANCE\` and the \`dev.php-legacy.openssl-route\` label."
  echo
  echo "Every claim on this page is about how a series is built, and every claim about a"
  echo "built image is checkable in the image:"
  echo "[DEPLOYING.md](DEPLOYING.md#checking-what-an-image-actually-contains) names the"
  echo "files to read, and [MAINTAINING.md](MAINTAINING.md#publishing-images) records"
  echo "what writes them and what is attested to the registry."
} > "${OUT}.tmp"

mv "${OUT}.tmp" "$OUT"
echo "Generated ${OUT}"
